/** Repeat only when the caller has confirmed this operation can be tried again. */
export async function retryAttempts(maxAttempts, runAttempt) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    const canRetry = attempt < maxAttempts;
    const { result, retry, beforeRetry } = await runAttempt(attempt, canRetry);
    if (!canRetry || !retry) return result;
    await beforeRetry?.();
  }
}
